<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { createWord, deleteWord, getWordPage, updateWord, type AdminWord } from '@/api/word'
const rows=ref<AdminWord[]>([]);const total=ref(0);const loading=ref(false);const dialog=ref(false);const editing=ref<number|null>(null);const form=reactive({content:'',source:''});const query=reactive({page:1,pageSize:10})
async function load(){loading.value=true;try{const r=await getWordPage(query);rows.value=r.records||[];total.value=r.total||0}finally{loading.value=false}}
function open(raw?:unknown){const row=raw as AdminWord|undefined;editing.value=row?.id||null;Object.assign(form,row||{content:'',source:''});dialog.value=true}
async function save(){if(!form.content.trim()){ElMessage.warning('请输入一言内容');return}if(editing.value===null)await createWord(form.content,form.source);else await updateWord(editing.value,form.content,form.source);dialog.value=false;ElMessage.success('保存成功');load()}
async function remove(raw:unknown){const row=raw as AdminWord;await ElMessageBox.confirm('确定删除该一言吗？','提示',{type:'warning'});await deleteWord(row.id);load()};onMounted(load)
</script>
<template><div class="word-page"><el-card shadow="never"><template #header><div class="header"><span>一言管理</span><el-button type="primary" @click="open">新增一言</el-button></div></template><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="content" label="内容" show-overflow-tooltip/><el-table-column prop="source" label="出处" width="180"/><el-table-column prop="createTime" label="创建时间" width="180"/><el-table-column label="操作" width="140"><template #default="s"><el-button link @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="editing===null?'新增一言':'编辑一言'"><el-form><el-form-item label="内容"><el-input v-model="form.content" type="textarea"/></el-form-item><el-form-item label="出处"><el-input v-model="form.source"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.word-page{padding:16px}.header{display:flex;justify-content:space-between}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
